# Try output[i][j] = input[j][W-1-i] where W=14
def check_mapping():
    errors = 0
    for i in range(14):
        for j in range(27):
            try:
                actual = demo_output[i][j]
                expected = demo_input[j][13-i]  # transpose the columns (flip horizontally at source)
                if actual != expected:
                    errors += 1
                    if errors <= 50:
                        print(f"First 50 mismatches:")
                        print(f"  output[{i}][{j}]='{actual}' != input[{j}][{13-i}]='{expected}'")
            except IndexError:
                break
    print(f"\nTotal errors with 'output[i][j] = input[j][13-i]': {errors}")
    return errors

check_mapping()

def check_rot90_ccw():
    errors = 0
    for i in range(14):
        for j in range(27):
            actual = demo_output[i][j]
            # rot90_ccw: output i,j = input j, 26-i
            expected = demo_input[j][26-i]
            if actual != expected:
                errors += 1
    print(f"Errors for rot90_ccw (output[i][j]=input[j][26-i]): {errors}")
    return errors

check_rot90_ccw()

